-- Source: HMDA (Home Mortgage Disclosure Act) Data (28301 rows)
-- Generated by gen_mart_models.py
--
-- Renamed 2026-08-06 (was housing__fed_cfpb_hmda): the underlying landing
-- table is Washington DC only (100% STATE_CODE = 'DC', a load-scope bug in
-- how the source was pulled, not a real geographic pattern). Loading the
-- true nationwide HMDA file is a separate, much larger job -- not done here.
-- The name now says what the data actually is so nobody mistakes this for
-- national coverage.

with source as (
    select * from {{ source('ripple_raw', 'FED_CFPB_HMDA') }}
)

select
